// Diagram callouts: no words are drawn on a diagram. Each label becomes a small numbered
// marker on the picture, and its words go in a key below the image.
//
// The labels in content.js were written as text placed on the image, sometimes over two or
// three lines. Lines that continue one another are merged into a single callout here, and
// each callout's marker sits where CALLOUT_POS (callout-positions.js, generated by
// scripts/place-callouts.mjs and reviewed by eye) puts it: on the part of the drawing the
// label describes. A callout with position 0 is a general note: listed in the key with no
// marker on the picture.
import { CALLOUT_POS } from './callout-positions.js';

const CHAR_W = 4.9; // width of one character at the labels' original 9.5 px size

function labelsOf(d) {
  return [0, 1, 2, 3, 4, 5, 6, 7].map((i) => d['l' + i]).filter((l) => l && l.t);
}

// Join a label's continuation lines (same column, next line down) into one callout.
export function mergeLabels(d) {
  const out = [];
  for (const l of labelsOf(d)) {
    const prev = out[out.length - 1];
    const last = prev && prev.lines[prev.lines.length - 1];
    if (last && last.a === l.a && Math.abs(last.x - l.x) <= 2 && l.y - last.y > 0 && l.y - last.y <= 13) {
      const joinTight = /[:,→(]$/.test(last.t) || /^[a-z(]/.test(l.t);
      prev.text += (joinTight ? ' ' : ' · ') + l.t;
      prev.lines.push(l);
      prev.amber = prev.amber || l.c === '#F5A623';
    } else {
      out.push({ text: l.t, lines: [l], amber: l.c === '#F5A623' });
    }
  }
  return out.map((m) => ({ ...m, box: boxOf(m.lines) }));
}

// Where the label's text used to sit (left, top, right, bottom in the 320×170 picture).
export function boxOf(lines) {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const l of lines) {
    const w = l.t.length * CHAR_W;
    const left = l.a === 'end' ? l.x - w : l.a === 'middle' ? l.x - w / 2 : l.x;
    x0 = Math.min(x0, left); x1 = Math.max(x1, left + w);
    y0 = Math.min(y0, l.y - 8); y1 = Math.max(y1, l.y + 2);
  }
  return [x0, y0, x1, y1];
}

// [{ n, text, x, y, amber }] — n is the marker number, or null for a note with no marker.
export function calloutsFor(id, d) {
  const merged = mergeLabels(d);
  const pos = CALLOUT_POS[id] || [];
  let n = 0;
  return merged.map((m, i) => {
    const p = pos[i];
    const [x0, y0, x1, y1] = m.box;
    const at = p === 0 ? null : p || [(x0 + x1) / 2, (y0 + y1) / 2];
    return { n: at ? ++n : null, text: m.text, x: at ? at[0] : null, y: at ? at[1] : null, amber: m.amber };
  });
}
